"""Validate structured facts; free business interpretation is deliberately not certified."""
import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

from app.domain.analysis_report import Insight
from app.domain.errors import AppError
from .evidence import fmt
from . import claims

# Numeric or statistical assertions are not permitted in free interpretation text.
NUMERIC = re.compile(r"[0-9０-９]|[零〇一二三四五六七八九十百千万亿两点]{2,}|第[一二三四五六七八九十百千万两]+|[一二三四五六七八九十两](?:成|倍|条|个|名|位|年|月)|百分之|半数|一半")
UNSUPPORTED_ASSERTION = re.compile(r"导致|造成|归因于|证明|必然|保证|因果|显著|最高|最低|排名|占比|翻倍|全部|所有|超过.*半|大多数")
UNSUPPORTED_BUSINESS_CLAIM = re.compile(
    r"(?:利润|盈利能力|经营效率|投入产出|profit|efficiency).{0,10}(?:更高|更好|较高|领先|优于|最佳|higher|better)|"
    r"(?:更高|更好|较高|领先|最佳).{0,8}(?:利润|盈利能力|经营效率)|"
    r"\b(?:causes?|proves?|guarantees?)\b", re.IGNORECASE)
# These express a limit on inference, not a positive statistical/business claim.
# Restrict the subject and objects; do not blanket-whitelist negated causal clauses.
INFERENCE_LIMIT = re.compile(
    r"(?:销售额)?排名(?:不能|无法|不足以|不直接)(?:证明|说明|代表|判断|推断)"
    r"(?:盈利能力|利润|经营效率|投入效果|资源投入效果)(?:或(?:盈利能力|利润|经营效率|投入效果|资源投入效果))*")
COMPATIBLE = {
    "highlight": {"metric", "ranking", "maximum", "minimum"},
    "difference": {"difference", "comparison"},
    "concentration": {"proportion", "comparison"},
    "trend": {"change_rate"},
    "coverage": {"coverage"},
}


def literal_fact(evidence):
    value = evidence.value
    if evidence.evidence_type == "coverage":
        return f"该任务记录的有效样本量为 {fmt(value['valid_samples'])}，上传数据共 {fmt(value['dataset_rows'])} 条记录。"
    if evidence.evidence_type in {"ranking", "maximum", "minimum"}:
        return f"{fmt(value['category'])}的已计算指标值为 {fmt(value['value'])}。"
    if evidence.evidence_type == "proportion":
        return f"{fmt(value['category'])}的分组指标为 {fmt(value['numerator'])}，同口径总体分母为 {fmt(value['denominator'])}。"
    if evidence.evidence_type in {"difference", "comparison"}:
        return f"两个被比较的已计算指标值分别为 {fmt(value['left_value'])} 与 {fmt(value['right_value'])}。"
    if evidence.evidence_type == "change_rate":
        return f"已返回首期值为 {fmt(value['baseline'])}，末期值为 {fmt(value['current'])}。"
    return evidence.statement


def semantic_key(e):
    if e.evidence_type in {'ranking', 'maximum', 'minimum'}:
        return (e.task_id, e.data_ref, e.result_field, 'point', str(e.value['category']), str(e.value['value']))
    return (e.task_id, e.data_ref, e.result_field, e.evidence_type, str(e.value))


def validate_comparison(e, tables=None):
    """Verify structured derived operands; the model never supplies these values."""
    kind = e.value.get('comparison_kind')
    if not kind:
        return
    try:
        value = e.value
        n, d, actual = (Decimal(str(value[k])) for k in ('numerator', 'denominator', 'percent'))
        a, b = (Decimal(str(value[k])) for k in ('left_value', 'right_value'))
        if not all(v.is_finite() for v in (n, d, actual, a, b)) or d <= 0:
            raise ValueError()
        if kind == 'relative_lead':
            valid = n == a - b and d == b and Decimal(str(value['difference'])) == n
        elif kind == 'relative_ratio':
            valid = n == a and d == b and a >= 0
        elif kind == 'returned_concentration':
            valid = n == a + b and 0 <= n <= d and value.get('denominator_scope') == 'returned_groups_only'
        else:
            valid = False
        with localcontext() as ctx:
            ctx.prec = max(28, actual.adjusted() + 10)
            if not valid or (n / d * 100).quantize(Decimal('.1'), rounding=ROUND_HALF_UP) != actual:
                raise ValueError()
        if tables is not None:
            table = tables[e.data_ref]
            field, dim = e.result_field, value['dimension_field']
            rows = [table.rows[index] for index in e.source_row_indices]
            if value.get('metric_field') != field or any(field not in row or dim not in row for row in rows):
                raise ValueError()
            ranked = sorted(Decimal(str(row[field])) for row in table.rows)
            if len(ranked) != len(set(ranked)) or value.get('unit') != '%':
                raise ValueError()
            if kind in {'relative_lead', 'returned_concentration'} and (a, b) != (ranked[-1], ranked[-2]):
                raise ValueError()
            if kind == 'relative_ratio' and (a, b) != (ranked[0], ranked[-1]):
                raise ValueError()
            left = [row[field] for row in rows if row[dim] == value['left']]
            right = [row[field] for row in rows if row[dim] == value['right']]
            if len(left) != 1 or len(right) != 1 or Decimal(str(left[0])) != a or Decimal(str(right[0])) != b:
                raise ValueError()
            if kind == 'returned_concentration' and (table.truncated or table.row_offset or
                    set(e.source_row_indices) != set(range(len(table.rows))) or
                    sum(Decimal(str(row[field])) for row in rows) != d):
                raise ValueError()
    except (ValueError, KeyError, IndexError, TypeError, ArithmeticError):
        raise AppError('REPORT_INVALID_COMPARISON', '比较证据的分子、分母、对象或结果来源不一致。', 502) from None


def validate_text(text, role, chosen=(), tasks=None, tables=None, trusted_limitations=(), diagnostics=None):
    """Conservative prose guard; finite verified references, not a semantic parser.

    Normalization below changes only the checking view. Original text is retained
    in the Insight and in audit metadata. Unknown factual claims still fail closed.
    """
    if role == 'limitation' and text in trusted_limitations:
        return
    checked = text
    verified = []
    def replace(old, new, rule):
        nonlocal checked
        if old in checked:
            checked = checked.replace(old, new)
            verified.append({'rule': rule, 'fragment': old})

    # Treat complete boundary phrases before any shorter phrase can destroy their
    # negation. A trailing affirmative clause is checked separately as before.
    for boundary in ['不保证时间点连续', '不是全部筛选范围或整体市场占比',
                     '不代表全部筛选范围或整体市场占比',
                     '不是全部筛选范围或整体市场', '不代表全部筛选范围或整体市场',
                     '不能仅凭返回表格确认所有分组均已覆盖',
                     '当前数据不足以判断造成差异的具体业务原因']:
        replace(boundary, '推断边界', 'NEGATIVE_BOUNDARY')
    temporal_result = bool(chosen and tables and any(c.role == 'dimension' and
        c.logical_type in {'date', 'datetime'} for c in tables[chosen[0].data_ref].columns))
    if chosen and (temporal_result or any(e.evidence_type == 'change_rate' for e in chosen)):
        # Endpoint equality is not interval stability, even when all sampled
        # endpoints happen to match. No stability evidence exists in V1.1.1.
        for clause in re.split(r'[，。；;]|但是|但|然而', checked):
            boundary = any(s in clause for s in ['不能判断', '无法判断', '不足以判断', '无法推断', '不能推断', '不足以推断'])
            future_check = role == 'recommendation' and clause.startswith(('核查', '验证', '进一步核查', '建议核查', '检查'))
            if '稳定' in clause and not (boundary or future_check):
                raise AppError('REPORT_UNVERIFIED_FACT', '首末比较不能证明期间稳定。', 502,
                    details={'rule': 'ENDPOINT_NOT_INTERVAL_STABILITY', 'role': role, 'text': text})
    for term in claims.pair_terms(chosen, tables):
        replace(term, '对应对象', 'BOUND_COMPARISON_OBJECTS')
    if claims.all_returned_equal(chosen, tables):
        replace('返回结果中所有分组', '本次返回分组', 'ALL_RETURNED_CELLS_EQUAL')
        replace('不编造唯一名次', '保留并列', 'BOUND_TIED_RANKING_BOUNDARY')
    if any(e.value.get('comparison_kind') == 'returned_concentration' for e in chosen):
        replace('前两个排名分组', '已比较对象', 'BOUND_CONCENTRATION_PAIR')
    ranks = {e.value['rank'] for e in chosen if e.evidence_type == 'ranking'}
    if {1, 2} <= ranks:
        replace('排名靠前', '已引用的前列对象', 'BOUND_RANKING_REFERENCE')
    if tasks and chosen:
        for step in tasks[chosen[0].task_id].steps:
            if step.operation == 'top_n' and isinstance(step.params.get('n'), int):
                n = step.params['n']
                for match in list(re.finditer(r'Top\s*'+str(n)+r'(?![0-9A-Za-z_])', checked, re.I)):
                    replace(match.group(), '已批准选择', 'BOUND_TOP_N')
        if role == 'limitation':
            for task in tasks.values():
                # Priority tokens are metadata only in an explicit task label.
                if task.title in checked:
                    replace(task.priority+'任务', '对应任务', 'BOUND_TASK_PRIORITY')
    has_ratio = any(e.evidence_type == 'proportion' or e.value.get('comparison_kind') in
                    {'returned_concentration', 'relative_ratio'} for e in chosen)
    if has_ratio:
        replace('不能直接视为总体占比', '分母范围边界', 'NEGATIVE_DENOMINATOR_BOUNDARY')
        replace('非总体占比', '分母范围边界', 'NEGATIVE_DENOMINATOR_BOUNDARY')
        for clause in re.split(r'[，。；;]|但是|但|然而', checked):
            if '占比' in clause and any(w in clause for w in ['整个', '全部', '总体', '市场份额']):
                # This term cannot be normalized merely because some ratio exists.
                raise AppError('REPORT_UNVERIFIED_FACT', '比例解释的总体范围未经证据绑定。', 502,
                    details={'rule': 'UNBOUND_POPULATION_SCOPE', 'role': role, 'text': text})
        # Only vocabulary, no amounts or ranking assertions are exempted. Numeric
        # prose and "最高" remain guarded after this scoped reference check.
        replace('占比', '构成', 'BOUND_RATIO_VOCABULARY')
    for allowed in ['不构成因果结论', '不能据此推断因果关系', '不代表因果关系']:
        checked = checked.replace(allowed, '')
    checked = INFERENCE_LIMIT.sub('', checked)
    checked = re.sub(r'(?:销售额)?(?:不能|无法|不足以)(?:证明|判断|推断)(?:盈利能力|利润|经营效率)', '', checked)
    checked = re.sub(r'(?:不能|无法|不足以|不可)(?:据此|直接)?(?:判断|评价|推断|认定)(?:人员绩效|员工绩效|经营表现|经营效率|盈利能力|利润|市场份额|录用机会)', '', checked)
    checked = re.sub(r'(?:不代表|不能代表|无法代表|不能外推至?)(?:全部筛选范围|整体市场|总体人群|总体|所有分组)(?:占比|比例)?', '', checked)
    checked = checked.replace('已返回的排名结果', '已返回的结果')
    # Ground bounded object-count references, never arbitrary metric values.
    # "两个渠道" describes a verified comparison pair, not two orders or years.
    pair = any('left' in e.value and 'right' in e.value for e in chosen)
    if pair:
        checked = re.sub(r'(?:这|该)?两(?:个(?:分组|城市|渠道|项目|类别)|类(?:工单|记录))|两者', '对应对象', checked)
    if any(e.value.get('comparison_kind') == 'returned_concentration' for e in chosen):
        checked = checked.replace('前两名', '已比较对象').replace('前两个返回分组', '已比较对象')
    if tasks and chosen:
        task = tasks[chosen[0].task_id]
        if role == 'limitation':
            for task_id in tasks:
                checked = re.sub(r'(?<![A-Za-z0-9_])'+re.escape(task_id)+r'(?![A-Za-z0-9_])', '对应任务', checked)
        for step in task.steps:
            if step.operation == 'top_n':
                n = step.params.get('n')
                if isinstance(n, int):
                    checked = re.sub(r'Top\s*'+str(n)+r'\b', '已批准选择', checked, flags=re.I)
                    chinese = {1:'一',2:'二',3:'三',4:'四',5:'五',6:'六',7:'七',8:'八',9:'九',10:'十'}.get(n)
                    if chinese:
                        checked = checked.replace('前'+chinese+'名', '已批准选择')
    # A negative inference boundary is not a positive causal or population claim.
    checked = re.sub(r'(?:不能|无法|不足以)(?:据此|直接)?归因于[^，。；;]*', '推断边界', checked)
    checked = checked.replace('不是全部筛选范围或整体市场占比', '分母范围边界')
    checked = checked.replace('不代表全部筛选范围或整体市场占比', '分母范围边界')
    checked = checked.replace('不能仅凭返回表格确认所有分组均已覆盖', '覆盖边界')
    if role == 'recommendation' and re.match(r'(?:建议|进一步|补充|比较|对比|核查|核对|确认|检查|评估|检验)', checked):
        # Future requests to investigate observable relationships are not completed causal proof.
        checked = re.sub(r'是否(?:由|与|源于)[^，。；;]*(?:驱动|引起|相关|导致|所致)', '待核查关联', checked)
        checked = checked.replace('占比', '构成').replace('排名', '排序')
    elif role == 'implication':
        checked = checked.replace('占比结构', '构成结构').replace('合计占比', '合计构成')
    # Numeric facts belong to deterministic composition, including English numeric claims.
    english_number = re.search(r'\b(?:zero|one|two|three|four|five|six|seven|eight|nine|ten|hundred|thousand|million|percent|percentage|ninety)\b', checked, re.I)
    causal = re.search(r'源自|源于|得益于|驱动|由于|因为|促成|决定了|带来.{0,12}(?:增长|下降|增加|减少)|\b(?:because|caus\w*|attribut\w*|proves?|guarantees?)\b', checked, re.I)
    business = re.search(r'(?:利润|盈利|效率|绩效|录用机会|营销效果|市场份额|profit|efficiency).{0,12}(?:高于|低于|更|领先|最佳|提升|改善|增加|下降|better|higher|greater)|(?:高于|低于|更高|更好|提升).{0,8}(?:利润|盈利|效率|profit|efficiency)', checked, re.I)
    completed = re.search(r'已(?:经)?(?:验证|证实|确定|找到|解释)|已完成(?:补充|后续|建议|进一步|全部|所有)|(?:核心|全部)目标.{0,5}已完成|事实证明|可以确定|足以说明|持续(?:增长|下降)|未来(?:将|会)', checked)
    threshold_claim = re.search(r'绝大部分|高度集中|规模优势|显著|相对差异较大|参与不足|竞争态势', checked)
    matches = {name: match.group() for name, match in [
        ('NUMERIC', NUMERIC.search(checked)), ('ENGLISH_NUMBER', english_number),
        ('CAUSAL', causal), ('BUSINESS_ASSERTION', business), ('COMPLETED_CLAIM', completed),
        ('UNDEFINED_THRESHOLD', threshold_claim), ('UNSUPPORTED_ASSERTION', UNSUPPORTED_ASSERTION.search(checked)),
        ('UNSUPPORTED_BUSINESS_CLAIM', UNSUPPORTED_BUSINESS_CLAIM.search(checked))] if match}
    if matches:
        raise AppError('REPORT_UNVERIFIED_FACT', '解释或建议包含未验证数值、原因、经营判断或已证实声明。', 502,
            details={'rule': 'FREE_TEXT_GUARD', 'role': role, 'text': text, 'matches': matches})
    if diagnostics is not None and verified:
        diagnostics.append({'role': role, 'original_text': text, 'checking_view': checked,
            'verified_references': verified, 'display_text_changed': False,
            'evidence_refs': [e.evidence_id for e in chosen]})


def materialize(draft, evidence, tasks, result_data=None, *, require_core=True, trusted_limitations=(), diagnostics=None):
    by_id = {item.evidence_id: item for item in evidence}
    insights = []
    seen = set()
    seen_facts = set()
    for index, item in enumerate(draft.insights):
        refs = item.evidence_refs
        if len(refs) != len(set(refs)) or not set(refs) <= by_id.keys() or item.primary_evidence_id not in refs:
            raise AppError("REPORT_INVALID_EVIDENCE_REFERENCE", "洞察引用不存在、重复或缺少主要证据。", 502)
        primary = by_id[item.primary_evidence_id]
        if primary.evidence_type not in COMPATIBLE[item.finding_type] or primary.evidence_id in seen:
            raise AppError("REPORT_INVALID_EVIDENCE_TYPE", "洞察类型与证据不匹配，或重复使用主要证据。", 502)
        chosen = [by_id[ref] for ref in refs]
        claims.compatible(primary, chosen)
        if item.finding_type == 'concentration' and primary.evidence_type == 'comparison' and primary.value.get('comparison_kind') != 'returned_concentration':
            raise AppError('REPORT_INVALID_EVIDENCE_TYPE', '集中度必须引用有明确分母的构成证据。', 502)
        atoms, keys = [], set()
        for e in chosen:
            claims.validate_source(e, result_data, tasks)
            validate_comparison(e, result_data)
            key = semantic_key(e)
            if key not in keys:
                atoms.append(e.statement.replace(' · ', ''))
                keys.add(key)
        if semantic_key(primary) in seen_facts or keys <= seen_facts:
            raise AppError('REPORT_DUPLICATE_FINDING', '该发现与已选择事实重复，没有新增证据信息。', 502)
        for role, text in [('implication', item.implication), ('recommendation', item.recommendation), *[('limitation', s) for s in item.limitations]]:
            validate_text(text, role, chosen, tasks, result_data, trusted_limitations, diagnostics)
        combined = claims.compose([e for e in chosen if semantic_key(e) in keys], result_data)
        detail = claims.fact_details(chosen)
        if len(combined) > 1800 or len(detail) > 2000:
            raise AppError('REPORT_FACT_COMPOSITION_TOO_LARGE', '单条事实组合过长，请减少重复证据。', 502)
        seen.add(primary.evidence_id)
        seen_facts.update(keys)
        # All selected atoms are expressed, not merely attached as invisible citations.
        insights.append(Insight(insight_id=f"I{index + 1:03d}", task_id=primary.task_id,
            fact=detail, finding=combined,
            implication='待验证的业务解释：' + item.implication[:1850],
            recommendation='下一步建议（尚未执行）：' + item.recommendation[:1850], evidence_refs=refs,
            limitations=[*item.limitations, '业务解释是待验证假设，未经过完整语义事实验证；不能据此推断因果关系。'] ))
    if require_core and {e.task_id for e in evidence if tasks[e.task_id].priority == 'P0'} - {i.task_id for i in insights}:
        raise AppError("REPORT_CORE_FINDINGS_MISSING", "洞察遗漏了已有证据的核心任务。", 502)
    return sorted(insights, key=lambda i: (tasks[i.task_id].priority, i.insight_id))


def materialize_candidates(draft, evidence, tasks, result_data, trusted_limitations=(), *, diagnostics=None, observer=None):
    """Isolate rejected candidates visibly. Never repair claims or invent fallback insights."""
    from app.domain.analysis_report import InsightDraft
    def observe(**payload):
        # Telemetry callbacks cannot change validation outcomes.
        if observer:
            try: observer(payload)
            except Exception: pass
    accepted, rejected, seen = [], [], set()
    by_id = {e.evidence_id: e for e in evidence}
    first_error = None
    for index, item in enumerate(draft.insights):
        try:
            candidate = materialize(InsightDraft(insights=[item]), evidence, tasks, result_data,
                require_core=False, trusted_limitations=trusted_limitations, diagnostics=diagnostics)[0]
            key = semantic_key(by_id[item.primary_evidence_id])
            if key in seen:
                raise AppError('REPORT_DUPLICATE_FINDING', '该候选发现重复，没有新增事实。', 502)
            seen.update(semantic_key(by_id[ref]) for ref in item.evidence_refs)
            candidate.insight_id = f'I{len(accepted) + 1:03d}'
            accepted.append(candidate)
            observe(candidate_index=index, candidate_status='accepted', primary_evidence_id=item.primary_evidence_id,
                evidence_refs=item.evidence_refs)
        except AppError as exc:
            first_error = first_error or exc
            # Rejected prose stays outside the saved business report. Keep rule
            # identity and binding diagnostics, never embed a rejected assertion
            # in metadata that might later be mistaken for a valid report fact.
            details = {k: v for k, v in exc.error.details.items() if k not in {'text', 'matches'}}
            if 'matches' in exc.error.details:
                details['triggered_rules'] = list(exc.error.details['matches'])
            rejected.append({'candidate_index': index, 'primary_evidence_id': item.primary_evidence_id,
                             'error_code': exc.error.code, 'details': details})
            observe(candidate_index=index, candidate_status='rejected', primary_evidence_id=item.primary_evidence_id,
                evidence_refs=item.evidence_refs, error_code=exc.error.code, role=details.get('role'),
                rule_ids=([details['rule']] if 'rule' in details else []) + details.get('triggered_rules', []))
    observe(candidate_count=len(draft.insights), accepted_count=len(accepted), rejected_count=len(rejected))
    if not accepted:
        error = first_error or AppError('REPORT_NO_VALID_INSIGHTS', '没有通过校验的洞察。', 502)
        error.error.details['rejected_candidates'] = rejected
        raise error
    missing_core = {e.task_id for e in evidence if tasks[e.task_id].priority == 'P0'} - {i.task_id for i in accepted}
    if missing_core:
        raise AppError('REPORT_CORE_FINDINGS_MISSING', '已有证据的核心任务未形成合法洞察，未保存完整报告。', 502)
    return sorted(accepted, key=lambda i: (tasks[i.task_id].priority, i.insight_id)), rejected

app/llm/templates.py.source:
"""Pin loaded instructions and verified composition sources, never infer old deployments."""
import ast
import importlib
import inspect
import json
import hashlib
from pathlib import Path
from types import CodeType
from datetime import datetime, timezone
from dataclasses import is_dataclass

from app.domain.errors import AppError
from app.domain.prompt_registry import PromptTemplateSnapshot, CallBinding
from app.observability.provenance import digest, git_snapshot
from app.storage.prompt_registry import template_content

COMPOSITION_VERSION = 'composition-v0.1'
MODULES = {
    'intent_parser': ['app.intent.prompt','app.intent.context','app.intent.validation','app.domain.intent'],
    'analysis_planner': ['app.planning.prompt','app.planning.context','app.planning.output',
        'app.planning.capabilities','app.planning.params','app.domain.analysis_plan','app.domain.intent'],
    'insight_generator': ['app.reporting.prompt','app.reporting.contracts','app.reporting.selection',
        'app.reporting.evidence','app.domain.analysis_report','app.review.presentation','app.review.constraint_audit'],
}
USER_KEYS = {
    'intent_parser': ['user_query','clarification_answers','dataset_context','validation_feedback?'],
    'analysis_planner': ['intent','core_requirements','profile','capabilities','validation_feedback?'],
    'insight_generator': ['analysis_goal','goal_coverage','original_query','constraints','constraints_confirmed',
        'scope_context','fields','uncompleted_tasks','task_sample_context','tasks','evidence','evidence_groups','limitations'],
}


def _shape(code):
    def constant(value):
        if isinstance(value, CodeType): return _shape(value)
        if isinstance(value, bytes): return {'bytes':value.hex()}
        if isinstance(value, slice): return {'slice':[constant(value.start),constant(value.stop),constant(value.step)]}
        if isinstance(value, complex): return {'complex':[value.real,value.imag]}
        if isinstance(value, (tuple, frozenset)): return [constant(v) for v in sorted(value,key=repr)] if isinstance(value,frozenset) else [constant(v) for v in value]
        if value is Ellipsis: return {'ellipsis':True}
        return value
    return {'bytecode':code.co_code.hex(),'constants':[constant(v) for v in code.co_consts],
        'names':code.co_names,'varnames':code.co_varnames,'freevars':code.co_freevars,'cellvars':code.co_cellvars,
        'argcount':code.co_argcount,'posonly':code.co_posonlyargcount,'kwonly':code.co_kwonlyargcount,'flags':code.co_flags,
        'exceptions':code.co_exceptiontable.hex()}


def _code_index(code):
    result = {code.co_qualname:code}
    for value in code.co_consts:
        if isinstance(value, CodeType): result.update(_code_index(value))
    return result


def _functions(value):
    if inspect.isfunction(value):
        yield value
    elif inspect.isclass(value) and value.__module__.startswith('app.'):
        for member in vars(value).values():
            if isinstance(member,(staticmethod,classmethod)): member=member.__func__
            if inspect.isfunction(member): yield member


def _source(module, actual_objects=()):
    path = Path(module.__file__).resolve()
    text = path.read_text()
    compiled = _code_index(compile(text, str(path), 'exec', dont_inherit=True))
    functions = []
    for value in vars(module).values():
        if getattr(value,'__module__',None) == module.__name__:
            functions.extend(f for f in _functions(value) if f.__module__ == module.__name__)
    for value in actual_objects:
        functions.extend(f for f in _functions(value) if f.__module__ == module.__name__)
    loaded = {}
    for function in functions:
        code = inspect.unwrap(function).__code__
        fresh = compiled.get(code.co_qualname)
        parent = vars(module).get(function.__qualname__.split('.')[0])
        if fresh is None and inspect.isclass(parent) and is_dataclass(parent) and inspect.unwrap(function).__code__.co_filename.startswith('<'):
            # dataclasses synthesizes these methods; retain their actual code fingerprints.
            loaded[function.__qualname__] = digest({'source':_shape(code),'wrapper':_shape(function.__code__)})
            continue
        if fresh is None or _shape(code) != _shape(fresh):
            raise AppError('PROMPT_SOURCE_MISMATCH','已加载组合逻辑与源码不同，请完整重启服务。',503)
        loaded[function.__qualname__] = digest({'source':_shape(code),'wrapper':_shape(function.__code__)})
    # Detect a changed literal (including version labels and mapping text) without executing source.
    literals = {}
    for statement in ast.parse(text).body:
        if isinstance(statement, ast.Assign):
            for target in statement.targets:
                if isinstance(target,ast.Name) and target.id.isupper():
                    try: literal=ast.literal_eval(statement.value)
                    except (ValueError,TypeError): continue
                    actual = getattr(module,target.id,object())
                    if not isinstance(literal,(dict,list,set)) and actual != literal:
                        raise AppError('PROMPT_SOURCE_MISMATCH','已加载固定指令与源码不同，请完整重启服务。',503)
                    try:
                        literals[target.id] = json.loads(json.dumps(actual,allow_nan=False))
                    except (TypeError,ValueError): pass
    root = Path(__file__).resolve().parents[2]
    return str(path.relative_to(root)), {'source':text, 'source_hash':hashlib.sha256(text.encode()).hexdigest(),
                                         'loaded_code_hashes':loaded,'loaded_literals':literals}


class TemplateSource:
    """Service-local pin. Rechecks loaded aliases at the call boundary, no prompt replay."""
    def __init__(self, node_id, service, version, system_prompt):
        self.node_id,self.service,self.version,self.system_prompt = node_id,service,version,system_prompt
        self.snapshot = self.build()

    def build(self):
        module = inspect.getmodule(type(self.service))
        prompt = importlib.import_module(MODULES[self.node_id][0])
        if (module.SYSTEM_PROMPT != self.system_prompt or prompt.SYSTEM_PROMPT != self.system_prompt
                or prompt.PROMPT_VERSION != self.version):
            raise AppError('PROMPT_SOURCE_MISMATCH','服务实际绑定的 Prompt 与版本来源不一致。',503)
        actual = [v for v in vars(module).values() if inspect.isfunction(v) or inspect.isclass(v)]
        names = list(dict.fromkeys([module.__name__, *MODULES[self.node_id],
            *[f.__module__ for v in actual for f in _functions(v) if f.__module__.startswith('app.')]]))
        # Capability handlers and the active instance schema are also real planning input sources.
        fixed = {}
        if hasattr(self.service,'registry'):
            fixed['capabilities'] = self.service.registry.summary()
            for spec in self.service.registry.operations.values():
                actual.extend([spec.handler,spec.params_model])
                names.extend([spec.handler.__module__,spec.params_model.__module__])
        sources = dict(_source(importlib.import_module(name),actual) for name in dict.fromkeys(names))
        composition = {'version':COMPOSITION_VERSION,'ordered_user_keys':USER_KEYS[self.node_id],
            'encoding':"json.dumps(ensure_ascii=False)", 'fixed_context':fixed,
            'retry_instructions':{k:v for k,v in vars(module).items() if k.endswith('_RETRY_INSTRUCTION')},
            'retry_instructions_source':module.__name__, 'scope_text_source':'app.review.presentation' if self.node_id=='insight_generator' else None}
        schema = {'intent_parser':'ParsedIntent.model_json_schema',
                  'analysis_planner':'CapabilityRegistry.request_schema + planning.output normalization',
                  'insight_generator':'InsightDraft schema + selected evidence ID enums'}[self.node_id]
        git = git_snapshot(Path(__file__).resolve().parents[3])
        provisional = PromptTemplateSnapshot(template_snapshot_id='',node_id=self.node_id,
            version=self.version+'+'+COMPOSITION_VERSION,content_hash='',system_template=self.system_prompt,
            user_composition=composition,output_schema_definition={'generator':schema},source_files=sources,
            source_commit=git.get('commit'),source_dirty=git.get('dirty'),created_at=datetime.now(timezone.utc).isoformat())
        content_hash = digest(template_content(provisional))
        return provisional.model_copy(update={'template_snapshot_id':'pt_'+content_hash,'content_hash':content_hash})

    def binding(self, operation_id, sequence=1, trace=None, retry_reason=None):
        current = self.build()
        if current.content_hash != self.snapshot.content_hash:
            raise AppError('PROMPT_SOURCE_MISMATCH','运行时组合内容已变化，拒绝使用旧模板标签。',503)
        run_id = trace.run.run_id if trace and trace.run else None
        span_id = trace.active.record.span_id if run_id and trace.active and trace.active.record else None
        return CallBinding(template=self.snapshot,operation_id=operation_id,call_sequence=sequence,
                           retry_index=sequence-1,retry_reason=retry_reason,run_id=run_id,span_id=span_id)


def pin_template(provider,node_id,service,version,system_prompt):
    # Scripted/custom providers retain their contract. Only the configured HTTP boundary persists real calls.
    return TemplateSource(node_id,service,version,system_prompt) if getattr(provider,'capture',None) is not None else None

app/reporting/claims.py.source:
"""Structured result/operand bindings. No natural-language inference or model calls.

Same-metric composition is supported by the current Draft contract. Cross-metric
facts may coexist as separate Insights; new cross-metric arithmetic needs an
explicit verified Evidence type, not a permanent ban on business comparisons.
"""
from dataclasses import dataclass
from decimal import Decimal
import math

from app.domain.errors import AppError
from .evidence import fmt


@dataclass(frozen=True)
class Binding:
    task_id: str
    result_id: str
    metric: str
    source_scope: str

    @classmethod
    def of(cls, evidence):
        return cls(evidence.task_id, evidence.data_ref, evidence.result_field,
                   evidence.value.get('source_scope', evidence.scope))


def compatible(primary, selected):
    if any(Binding.of(e) != Binding.of(primary) for e in selected):
        raise AppError('REPORT_INVALID_EVIDENCE_REFERENCE',
            '当前单条洞察只支持同指标同范围组合；跨指标事实请分别展示，派生计算需独立验证证据。', 502,
            details={'rule': 'SAME_METRIC_COMPOSITION',
                     'bindings': [Binding.of(e).__dict__ for e in selected]})


def decimal(value):
    if isinstance(value, bool) or value is None:
        raise ValueError('Not numeric')
    result = Decimal(str(value))
    if not result.is_finite():
        raise ValueError('Nonfinite')
    return result


def same(actual, expected, *, derived=False):
    a, b = decimal(actual), decimal(expected)
    if a == a.to_integral_value() and b == b.to_integral_value():
        return a == b
    # Raw cells/ranks are exact. Only legacy float-derived arithmetic has a
    # relative tolerance, with no absolute floor that could erase tiny results.
    return a == b or (derived and math.isclose(float(a), float(b), rel_tol=1e-12, abs_tol=0))


def dimension(table):
    dims = [c.field for c in table.columns if c.role == 'dimension']
    return dims[0] if len(dims) == 1 else None


def validate_source(e, tables, tasks):
    """Recheck all base evidence against result cells, not only new ratios.

Execution sample counts are validated by report contracts and created from the
ExecutionResult, never supplied by the LLM. They have no result-table cell.
"""
    if tables is None:
        return
    try:
        table = tables[e.data_ref]
        if e.evidence_type == 'coverage':
            if e.result_field != '$execution.valid_sample_count' or e.source_row_indices:
                raise ValueError()
            return
        field, value = e.result_field, e.value
        col = next(c for c in table.columns if c.field == field and c.role == 'metric')
        indices = e.source_row_indices
        if not indices or len(indices) != len(set(indices)) or any(i < 0 or i >= len(table.rows) for i in indices):
            raise ValueError()
        rows = [table.rows[i] for i in indices]
        dim = dimension(table)
        pairs = [(i, decimal(r[field])) for i, r in enumerate(table.rows) if r[field] is not None]
        kind = e.evidence_type
        if kind in {'ranking', 'maximum', 'minimum'}:
            target = decimal(value['value'])
            if not dim or any(r[dim] != value['category'] for r in rows[:1]) or any(decimal(r[field]) != target for r in rows):
                raise ValueError()
            if kind == 'ranking' and (len(rows) != 1 or value['rank'] != 1 + sum(v > target for _, v in pairs)):
                raise ValueError()
            if kind != 'ranking':
                expected = (max if kind == 'maximum' else min)(v for _, v in pairs)
                if target != expected or set(indices) != {i for i, v in pairs if v == target} or value['tie_count'] != len(indices):
                    raise ValueError()
        elif kind == 'metric':
            expected = sum(decimal(r[field]) for r in rows)
            if len(rows) > 1:
                aggregates = [s for s in tasks[e.task_id].steps if s.operation in {'aggregate', 'group_aggregate'}]
                metric = next(m for m in aggregates[-1].params['metrics'] if m['alias'] == field)
                if metric['function'] not in {'sum', 'count'} or table.truncated or table.row_offset or set(indices) != set(range(len(table.rows))):
                    raise ValueError()
            if not same(value['value'], expected, derived=len(rows)>1) or value.get('unit') != col.unit:
                raise ValueError()
        elif kind in {'difference', 'comparison'} and not value.get('comparison_kind'):
            if 'left_field' in value:  # Existing explicit scalar comparison evidence.
                a, b = rows[0][value['left_field']], rows[0][value['right_field']]
            else:
                if not dim or len(rows) != 2 or rows[0][dim] != value['left'] or rows[1][dim] != value['right']:
                    raise ValueError()
                a, b = rows[0][field], rows[1][field]
            if not same(value['left_value'], a) or not same(value['right_value'], b) or not same(value['difference'], decimal(a)-decimal(b), derived=True):
                raise ValueError()
        elif kind == 'change_rate':
            if not dim or len(rows) != 2 or rows[0][dim] != value['from'] or rows[1][dim] != value['to']:
                raise ValueError()
            a, b = decimal(rows[0][field]), decimal(rows[1][field])
            if a <= 0 or not same(value['baseline'], a) or not same(value['current'], b) or not same(value['change_percent'], (b-a)/a*100, derived=True):
                raise ValueError()
        elif kind == 'proportion':
            if not dim or len(rows) != 1 or rows[0][dim] != value['category'] or not same(value['numerator'], rows[0][field]):
                raise ValueError()
            refs = [r for r in table.total_refs if r.metric_field == field]
            if refs:
                ref = refs[0]
                denominator = tables[ref.result_id].rows[0][ref.result_field]
                if ref.result_id not in e.related_result_refs:
                    raise ValueError()
            else:
                task = tasks[e.task_id]
                last_group = max(i for i, s in enumerate(task.steps) if s.operation == 'group_aggregate')
                if table.truncated or table.row_offset or any(s.operation in {'filter', 'top_n'} for s in task.steps[last_group+1:]):
                    raise ValueError()
                metric = next(m for m in task.steps[last_group].params['metrics'] if m['alias'] == field)
                if metric['function'] not in {'sum', 'count'} or len(pairs) != len(table.rows):
                    raise ValueError()
                denominator = sum(v for _, v in pairs)
            if decimal(denominator) <= 0 or not same(value['denominator'], denominator, derived=True) or not same(value['percent'], decimal(value['numerator'])/decimal(denominator)*100, derived=True):
                raise ValueError()
    except (ValueError, KeyError, IndexError, TypeError, StopIteration, ArithmeticError):
        raise AppError('REPORT_INVALID_FACT_BINDING', '证据的对象、指标、数值、排名或分母与计算结果不一致。', 502,
                       details={'rule': 'RESULT_CELL_BINDING', 'evidence_id': e.evidence_id}) from None


def all_returned_equal(selected, tables):
    if not selected or not tables:
        return False
    e = selected[0]
    table = tables[e.data_ref]
    values = [r.get(e.result_field) for r in table.rows]
    return (not table.truncated and not table.row_offset and bool(values) and
            all(v is not None for v in values) and len({decimal(v) for v in values}) == 1 and
            set(range(len(values))) <= {i for x in selected for i in x.source_row_indices})


def pair_terms(selected, tables):
    """Finite grammatical aliases backed by the actual dimension, not guessed topics."""
    if not tables or not selected or not any(('left' in e.value and 'right' in e.value) or e.evidence_type == 'change_rate' for e in selected):
        return []
    table = tables[selected[0].data_ref]
    dims = [c for c in table.columns if c.role == 'dimension']
    if len(dims) != 1:
        return []
    label = dims[0].label
    nouns = {label}
    if dims[0].logical_type in {'date', 'datetime'}:
        nouns.update({'时间点', '日期'})
    aliases = {'岗位类型': {'类岗位'}, '工单类型': {'类工单'}, '类别': {'类别', '类记录'}, '城市': {'城市'}}
    nouns.update(aliases.get(label, set()))
    return ['两者', '两个分组', *('两'+n if n.startswith('类') else '两个'+n for n in nouns)]


def render(e, table):
    """Canonical facts use structured operands, never model-provided numeric prose."""
    v = e.value
    column = next((c for c in table.columns if c.field == e.result_field), None)
    label = column.label.replace(' · ', '') if column else '记录'
    unit = column.unit or '' if column else ''
    kind = e.evidence_type
    if kind == 'coverage':
        return f"有效样本量 {fmt(v['valid_samples'])} 条，上传数据 {fmt(v['dataset_rows'])} 条。"
    if kind == 'metric':
        return f"{v.get('label', label)}为 {fmt(v['value'])}{unit}。"
    if kind in {'ranking', 'maximum', 'minimum'}:
        suffix = f"，返回结果内排名 {v['rank']}（并列同名次）" if kind == 'ranking' else f"，为返回结果{'最大' if kind == 'maximum' else '最小'}值"
        return f"{fmt(v['category'])}的{label}为 {fmt(v['value'])}{unit}{suffix}。"
    if kind == 'proportion':
        return f"{fmt(v['category'])}的{label}占已验证同口径总体的 {fmt(v['percent'])}%（分母 {fmt(v['denominator'])}{unit}）。"
    if kind == 'change_rate':
        return f"{fmt(v['from'])}至{fmt(v['to'])}，{label}从 {fmt(v['baseline'])} 变为 {fmt(v['current'])}，首末变化 {fmt(v['change_percent'])}%；不代表期间连续趋势。"
    ck = v.get('comparison_kind')
    if ck == 'relative_lead':
        return f"{fmt(v['left'])}的{label}比{fmt(v['right'])}高 {fmt(decimal(v['difference']))}{unit}，相对{fmt(v['right'])}高 {v['percent']}%。"
    if ck == 'relative_ratio':
        return f"{fmt(v['left'])}的{label}为 {fmt(decimal(v['left_value']))}{unit}，是{fmt(v['right'])}的 {v['percent']}%。"
    if ck == 'returned_concentration':
        return f"{fmt(v['left'])}和{fmt(v['right'])}合计占本次返回 {v['returned_group_count']} 个分组{label}的 {v['percent']}%；分母 {fmt(decimal(v['denominator']))}{unit}仅为返回分组合计，不是筛选范围总体。"
    left = v.get('left', v.get('left_field'))
    right = v.get('right', v.get('right_field'))
    return f"{fmt(left)}与{fmt(right)}的{label}差值为 {fmt(v['difference'])}{unit}。"


def compose(selected, tables):
    kept, seen = [], set()
    # A relative lead already carries the same absolute difference. Keep citations
    # but do not repeat the atom. Avoid dropping facts merely because numbers match.
    for e in selected:
        key = (e.result_field, str(e.value.get('category')), str(e.value.get('value')))
        if e.evidence_type in {'ranking', 'maximum', 'minimum'}:
            if key in seen:
                continue
            seen.add(key)
        redundant = e.evidence_type == 'difference' and any(
            x.value.get('comparison_kind') == 'relative_lead' and
            all(str(e.value.get(k)) == str(x.value.get(k)) for k in ['left', 'right', 'difference']) for x in selected)
        if not redundant:
            kept.append(render(e, tables[e.data_ref]) if tables else e.statement.replace(' · ', ''))
    return ' '.join(dict.fromkeys(kept))


def fact_details(selected):
    """Compact operand record for the expandable fact field, not another finding."""
    labels = {'category':'对象', 'value':'指标值', 'rank':'返回排名', 'left':'比较对象', 'right':'基准对象',
        'left_value':'对象值', 'right_value':'基准值', 'difference':'差值', 'numerator':'分子',
        'denominator':'分母', 'percent':'比例(%)', 'from':'首期', 'to':'末期',
        'baseline':'首期值', 'current':'末期值', 'change_percent':'首末变化(%)',
        'valid_samples':'有效样本量', 'dataset_rows':'上传行数'}
    parts = []
    for e in selected:
        fields = '，'.join(f'{label}={fmt(e.value[key])}' for key,label in labels.items() if key in e.value)
        parts.append(f'{e.evidence_id}（{e.result_field}）：{fields}')
    return '；'.join(parts)


def missing_metrics(evidence, tasks, insights):
    by_id = {e.evidence_id: e for e in evidence}
    required = {(e.task_id, e.result_field) for e in evidence
                if tasks[e.task_id].priority == 'P0' and not e.result_field.startswith('$')}
    covered = {(by_id[r].task_id, by_id[r].result_field) for i in insights for r in i.evidence_refs
               if r in by_id and not by_id[r].result_field.startswith('$')}
    return sorted(required-covered)

